contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _val, bool doInit) public payable {
        uint before;
        bool reverted1;
        bool reverted2;
        uint after1;
        uint after2;

        // Read MinSum before
        before = c.MinSum();

        // Optionally initialize
        if (doInit) {
            c.Initialized();
        }

        // First SetMinSum call
        try c.SetMinSum(_val) { reverted1 = false; } catch { reverted1 = true; }
        after1 = c.MinSum();

        // If not initialized yet, also test a second call with different value to show it still works until init
        // Actually we only have one call per state; we can do a second call after initialization if doInit was false? Not needed.
        // We need a general rule that holds for all inputs.
        // The rule: if not initialized, SetMinSum(_val) does not revert and MinSum becomes _val.
        // If initialized, SetMinSum(_val) reverts and MinSum unchanged (from before or after first call).
        // But we have a single call here; after1 is the MinSum after the call.
        // For the case doInit==true, the call is after initialization, so it should revert and MinSum should remain whatever it was before the call (which is 'before' because Initialized doesn't change MinSum).
        // For doInit==false, the call is before initialization, so it should not revert and MinSum should become _val.
        // So we can assert: (doInit ? (reverted1 && after1 == before) : (!reverted1 && after1 == _val)).

        assert(doInit ? (reverted1 && after1 == before) : (!reverted1 && after1 == _val));
    }

    receive() external payable {}
}

